let nodeExecutions = [];
let llmUsages = [];

function estimateTokens(textStr) {
    if (!textStr) return 0;
    return Math.ceil(textStr.length / 3.0);
}
// USD per 1K tokens (blended in/out estimate, OpenRouter list prices Sept 2026)
const MODEL_COSTS = {
  'z-ai/glm-5.3-flash:floor': 0.00016,
  'z-ai/glm-5.3-flash': 0.00016,
  'deepseek/deepseek-v4.1-flash': 0.00034,
  'meta-llama/llama-3.3-70b-instruct': 0.0003
};
function getCost(modelName) { return MODEL_COSTS[modelName] || 0.0002; }

function extractTokenUsage(agentNodeName, promptText, agentOutputJson) {
    let fallbackPromptTokens = estimateTokens(promptText);
    let outputText = typeof agentOutputJson === 'string' ? agentOutputJson : JSON.stringify(agentOutputJson);
    let fallbackCompletionTokens = estimateTokens(outputText);

    // Try natively
    try {
        let usage = $(agentNodeName).last().json.tokenUsage;
        if (usage && usage.promptTokens) {
            return {
                promptTokens: usage.promptTokens,
                completionTokens: usage.completionTokens || usage.completion_tokens || fallbackCompletionTokens,
                totalTokens: usage.totalTokens || usage.total_tokens || (usage.promptTokens + fallbackCompletionTokens)
            };
        }
    } catch(e) {}

    return { 
        promptTokens: fallbackPromptTokens, 
        completionTokens: fallbackCompletionTokens, 
        totalTokens: fallbackPromptTokens + fallbackCompletionTokens 
    };
}

try {
    let migStart = $('Pre-Migrator Chain Telemetry').first()?.json?.agent_start || 0;

    let errorFixerStarts = [];
    try {
        let eStarts = $('Pre-Error Fixer Chain Telemetry').all();
        if (eStarts) errorFixerStarts = eStarts.map(s => s.json.agent_start);
    } catch(e) {}

    let repStart = $('Pre-Reporter Agent Telemetry').first()?.json?.agent_start || 0;


    // Precise execution times from Post nodes
    let migEnd = $('Post-Migrator Chain Telemetry').first()?.json?.agent_end || migStart + 45000;
    let migTime = migEnd - migStart;

    let errTime = 0;
    if (errorFixerStarts.length > 0) {
        try {
            let eEnds = $('Post-Error Fixer Chain Telemetry').all();
            for (let i = 0; i < Math.min(errorFixerStarts.length, eEnds.length); i++) {
                errTime += (eEnds[i].json.agent_end - errorFixerStarts[i]);
            }
        } catch(e) {}
    }

    let repEnd = $('Post-Reporter Agent Telemetry').first()?.json?.agent_end || repStart + 15000;
    let repTime = repEnd - repStart;

    nodeExecutions.push({ NodeName: 'Build Action List', Phase: 'Phase 2', ExecutionTimeMs: migTime });
    if (errorFixerStarts.length > 0) {
        nodeExecutions.push({ NodeName: 'Error Fixer Chain', Phase: 'Phase 2', ExecutionTimeMs: errTime });
    }
    nodeExecutions.push({ NodeName: 'Reporter Agent', Phase: 'Phase 2', ExecutionTimeMs: repTime });

    // LLM Usages

    // v5.2: no Migrator LLM - that step is a Code node now.
    let errModel = "z-ai/glm-5.3-flash:floor";
    try { errModel = $evaluateExpression('{{ $node["Error Fixer LLM"].parameter.model }}') || errModel; } catch(e) {}
    let repModel = "z-ai/glm-5.3-flash:floor";
    try { repModel = $evaluateExpression('{{ $node["Reporter LLM"].parameter.model }}') || repModel; } catch(e) {}

    // v5.2: the Migrator is a Code node - no model, no tokens, no usage row.

    if (errorFixerStarts.length > 0) {
        let errOutput = $('Error Fixer Chain').last()?.json || {};
        let errPromptStr = "Error Fixer Prompt" + (JSON.stringify($('Log Build Output').last()?.json) || "").substring(0, 15000);
        let errUsage = extractTokenUsage('Error Fixer Chain', errPromptStr, errOutput);
        llmUsages.push({
            AgentName: 'Error Fixer Chain',
            ModelName: errModel,
            Provider: 'OpenRouter (estimated)',
            PromptTokens: errUsage.promptTokens * errorFixerStarts.length,
            CompletionTokens: errUsage.completionTokens * errorFixerStarts.length,
            TotalTokens: errUsage.totalTokens * errorFixerStarts.length,
            TotalCostUsd: ((errUsage.totalTokens * errorFixerStarts.length) / 1000) * getCost(errModel)
        });
    }

    let repOutput = $('Reporter Agent').last()?.json || {};
    let repPromptStr = "Reporter Prompt" + (JSON.stringify($('Log Generating Diffs').first()?.json) || "").substring(0, 5000);
    let repUsage = extractTokenUsage('Reporter Agent', repPromptStr, repOutput);
    llmUsages.push({
        AgentName: 'Reporter Agent',
        ModelName: repModel,
        Provider: 'OpenRouter (estimated)',
        PromptTokens: repUsage.promptTokens,
        CompletionTokens: repUsage.completionTokens,
        TotalTokens: repUsage.totalTokens,
        TotalCostUsd: (repUsage.totalTokens / 1000) * getCost(repModel)
    });

} catch(e) {
    // If it fails, log error string instead of crashing silently
    llmUsages.push({
        AgentName: 'TelemetryScriptError',
        ModelName: e.message.substring(0,50),
        Provider: 'Error',
        PromptTokens: 0,
        CompletionTokens: 0,
        TotalTokens: 0,
        TotalCostUsd: 0
    });
