// Error Fixer tool: replace an exact snippet.
//
// The point of making this a tool rather than a JSON action: the model gets the
// result of THIS edit before it decides the next one. In the v5.x design it had
// to emit every edit blind in one array, and a failure came back as a synthetic
// "API REPLACE ERROR" pushed into the next build output.
const helpers = this.helpers;
const filePath = String(query.filePath || '').trim();
const oldText = query.oldText;
const newText = query.newText;

if (!filePath) return 'ERROR: filePath is required.';
if (typeof oldText !== 'string' || !oldText.length) {
  return 'ERROR: oldText must be a non-empty string. To insert code, include the surrounding existing lines in oldText and put both them and the new lines in newText.';
}
if (typeof newText !== 'string') return 'ERROR: newText is required (use an empty string to delete).';

const clean = filePath.replace(/^\/?projects\/migration-\d+\//, '').replace(/^\//, '');

try {
  const res = await helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/files/replace',
    body: {
      jobId: Number($('Execute Webhook').first().json.body.job_id),
      filePath: clean,
      targetContent: oldText,
      replacementContent: newText
    },
    json: true
  });
  // /api/files/replace answers 200 with success:false when the snippet does not
  // match - it is not an HTTP error, so the body is the only signal.
  const ok = res && (res.success === true || res.Success === true);
  if (ok) return 'OK: replaced in ' + clean + '.';
  const msg = (res && (res.message || res.Message)) || 'unknown reason';
  return 'FAILED on ' + clean + ': ' + msg +
    '\nThe file was NOT changed. Read it again with read_file and copy the exact current text - ' +
    'an earlier edit in this same run may already have changed these lines.';
} catch (e) {
  return 'FAILED on ' + clean + ': ' + e.message;
}

