// Error Fixer tool: add, re-pin or remove a PackageReference.
//
// Deliberately NOT a general shell tool. The v5.x design gave the model an
// ExecuteCommand action whose string went straight into `sh -c` via
// 'cd /projects/migration-N && ' + $json.command, so one stray quote made the
// behaviour undefined. The only shell capability the Error Fixer actually needs
// is add/remove/re-pin for NU1605 downgrades and missing references.
//
// There is no command endpoint on the backend (/api/files/{read,write,replace,grep}
// and /api/csproj/update, which only does the TargetFramework), so this does the
// XML edit itself and writes the whole file back. `dotnet build` runs immediately
// after and does the restore, so a bad version still surfaces as a build error on
// the next iteration rather than being silently accepted here.
const helpers = this.helpers;
const action = String(query.action || 'add').trim().toLowerCase();
const project = String(query.project || '').trim().replace(/^\/?projects\/migration-\d+\//, '').replace(/^\//, '');
const name = String(query.packageId || '').trim();
const version = String(query.version || '').trim();

if (!project || !/\.csproj$/i.test(project)) return 'ERROR: project must be a relative path to a .csproj, e.g. src/Api/Api.csproj';
if (!name) return 'ERROR: packageId is required.';
if (['add', 'remove'].indexOf(action) === -1) return 'ERROR: action must be "add" or "remove".';
if (!/^[A-Za-z0-9._-]+$/.test(name)) return 'ERROR: packageId is not a valid package id.';
if (action === 'add' && !version) return 'ERROR: version is required when adding. Take it from the build error, do not guess.';
if (version && !/^[A-Za-z0-9.*+-]+$/.test(version)) return 'ERROR: version is not a valid version string.';

const FRAMEWORK_REFS = ['microsoft.netcore.app', 'microsoft.aspnetcore.app', 'microsoft.windowsdesktop.app'];
if (FRAMEWORK_REFS.indexOf(name.toLowerCase()) !== -1) {
  return 'ERROR: ' + name + ' is an implicit framework reference, not a NuGet package. Adding it breaks the build.';
}

const jobId = Number($('Execute Webhook').first().json.body.job_id);

try {
  const read = await helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/files/read',
    body: { jobId: jobId, filePath: project },
    json: true
  });
  let xml = (typeof read === 'string') ? read : (read.content || read.Content || '');
  if (!xml) return 'ERROR: could not read ' + project;

  const esc = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const existing = new RegExp('[ \\t]*<PackageReference\\s+Include="' + esc + '"[^>]*?/>\\s*\\r?\\n?', 'i');
  const hasIt = existing.test(xml);
  let what;

  if (action === 'remove') {
    if (!hasIt) return 'No change: ' + project + ' does not reference ' + name + '.';
    xml = xml.replace(existing, '');
    what = 'removed ' + name;
  } else if (hasIt) {
    xml = xml.replace(existing, '    <PackageReference Include="' + name + '" Version="' + version + '" />\n');
    what = 're-pinned ' + name + ' to ' + version;
  } else {
    const line = '    <PackageReference Include="' + name + '" Version="' + version + '" />\n';
    const lastRef = xml.lastIndexOf('</PackageReference>') > -1 ? -1 : xml.search(/[ \t]*<PackageReference\b[^>]*\/>\s*\r?\n/);
    if (lastRef > -1) {
      // Put it next to the existing PackageReferences, in their ItemGroup.
      const after = xml.indexOf('\n', xml.indexOf('/>', lastRef)) + 1;
      xml = xml.slice(0, after) + line + xml.slice(after);
    } else {
      const close = xml.lastIndexOf('</Project>');
      if (close === -1) return 'ERROR: ' + project + ' has no </Project> element; refusing to edit it.';
      xml = xml.slice(0, close) + '  <ItemGroup>\n' + line + '  </ItemGroup>\n' + xml.slice(close);
    }
    what = 'added ' + name + ' ' + version;
  }

  const write = await helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/files/write',
    body: { jobId: jobId, filePath: project, content: xml },
    json: true
  });
  const ok = write && (write.success === true || write.Success === true);
  return ok
    ? 'OK: ' + what + ' in ' + project + '. The next build will restore it.'
    : 'FAILED writing ' + project + ': ' + ((write && (write.message || write.Message)) || 'unknown reason');
} catch (e) {
  return 'FAILED on ' + project + ': ' + e.message;
}

